from dataclasses import dataclass


@dataclass
class EmailContent:
    """
    Represents the textual content of an email in plaintext and HTML forms.
    """

    subject: str
    body_plaintext: str
    body_html: str | None = None

    # Technically a header but included because it's generated by code that makes the body of the email,
    # since the body will typically contain an unsubscribe link to this URL.
    list_unsubscribe_url: str | None = None
